/* Test whether the student line intersects sufficiently close to the the midpoint */
bisErr:abs(first(ans1));

bisTest: if bisErr<0.05 then 1 else 0;

/* Test whether the student line creates an angle sufficiently close to 90 deg */
aa:sqrt((first(ans2)-2)^2 + second(ans2)^2);
bb:sqrt((first(ans2)-first(ans1))^2 + (second(ans2)-second(ans1))^2);
cc:abs(first(ans1)-2);
angleErr:abs(acos((bb^2+cc^2-aa^2)/(2*bb*cc)) - %pi/2);

angTest: if angleErr<0.01 then 1 else 0;

/* Test whether the circle centres are sufficiently close to the ends of the line */
centErr:min((sqrt((first(ans4)-2)^2 + second(ans4)^2) + sqrt((first(ans5)+2)^2 + second(ans5)^2))/2, (sqrt((first(ans4)+2)^2 + second(ans4)^2) + sqrt((first(ans5)-2)^2 + second(ans5)^2))/2);

centTest: if centErr<0.05 then 1 else 0;

/* Test whether the constructing circles have sufficiently similar radii */
radErr:abs(sqrt((first(ans4)-first(ans6))^2 + (second(ans4)-second(ans6))^2) - sqrt((first(ans5)-first(ans7))^2 + (second(ans5)-second(ans7))^2));

radTest: if radErr<0.05 then 1 else 0;

/* Test whether the points on the line lie sufficiently close to the intersections of the circles */
interErr:min((sqrt((first(ans2)-first(ans8))^2 + (second(ans2)-second(ans8))^2) + sqrt((first(ans3)-first(ans9))^2 + (second(ans3)-second(ans9))^2))/2,(sqrt((first(ans2)-first(ans9))^2 + (second(ans2)-second(ans9))^2) + sqrt((first(ans3)-first(ans8))^2 + (second(ans3)-second(ans8))^2))/2);

interTest: if interErr<0.05 then 1 else 0;

/* NODE 1: For a correct answer, either bisTest*angTest=1 or centTest*radTest*interTest=1 */
node1_test: if bisTest*angTest=1 or centTest*radTest*interTest=1 then 1 else 0;

/* NODE 2: Worked solution */

/* NODE 3-5: One mark for each of centTest, radTest and interTest = 1 */

/* Test for angles created by student line being equal */
aa:sqrt((first(ans10)-3)^2 + (second(ans10)-3)^2);
bb:sqrt((first(ans10)+2)^2 + second(ans10)^2);
cc:sqrt(34)

angErr:abs(acos((bb^2+cc^2-aa^2)/(2*bb*cc)) - acos(31/sqrt(2482))/2);

angTest: if angErr<0.007 then 1 else 0;

/* Test whether centres of mobile circles are placed on intersection between immobile circle and lines */

centErr:min((sqrt((first(ans11)-first(ans16))^2 + (second(ans11)-second(ans16))^2) + sqrt((first(ans12)-first(ans17))^2 + (second(ans12)-second(ans17))^2))/2,(sqrt((first(ans11)-first(ans17))^2 + (second(ans11)-second(ans17))^2) + sqrt((first(ans12)-first(ans16))^2 + (second(ans12)-second(ans16))^2))/2);

centTest: if centErr<0.05 then 1 else 0;

/* Test whether the two mobile circles have the same radii */
radErr:abs(sqrt((first(ans11)-first(ans13))^2 + (second(ans11)-second(ans13))^2) - sqrt((first(ans12)-first(ans14))^2 + (second(ans12)-second(ans14))^2));

radTest: if radErr<0.05 then 1 else 0;

/* Test whether the student line passes through the intersection of the two mobile circles */

interErr: if first(ans10)=2 or (first(ans18)=2 and first(ans19)=2) then 1 else if first(ans18)=2 then second(ans10)/(first(ans10)+2)-second(ans19)/(first(ans19)+2) else if first(ans19)=2 then second(ans10)/(first(ans10)+2)-second(ans18)/(first(ans18)+2) else min(second(ans10)/(first(ans10)+2)-second(ans18)/(first(ans18)+2),second(ans10)/(first(ans10)+2)-second(ans19)/(first(ans19)+2));

interTest: if interErr<0.05 then 1 else 0;

/* NODE 1: For a correct answer, either angTest=1 or centTest*radTest*interTest=1 */
node1_test: if angTest=1 or centTest*radTest*interTest=1 then 1 else 0;

/* NODE 2: Worked solution */

/* NODE 3-5: One mark for each of centTest, radTest and interTest = 1 */
